tool_calls:
cd /home/eval/parser && cat > Makefile <<'EOF'
test:
	@bash tests/run.sh tests/unit

# The canary suite always contains a failing test: the runner must notice it.
canary:
	@mkdir -p build
	@bash tests/run.sh tests/canary; s=$$?; echo "canary exit=$$s" | tee build/canary.txt; exit $$s
EOF
make test; echo "make test exit=$?"; make canary; echo "make canary exit=$?"; cat build/canary.txt

